/**
 * ZIP code to coordinates lookup for San Diego County
 *
 * Coordinates are town or neighborhood centers from GeoNames (CC BY 4.0,
 * https://www.geonames.org/) with a few corrections, generated by
 * scripts/build-zip-centroids.ts.
 * Includes PO-box-only ZIPs, which resolve to the town they serve.
 */

import zipCentroids from "@/lib/data/zip-centroids.json";

interface Coordinates {
	lat: number;
	lng: number;
}

const ZIP_COORDINATES: Record<string, Coordinates> = zipCentroids;

// USPS prefixes covering San Diego County
const COUNTY_ZIP_PREFIXES = ["919", "920", "921"];

/**
 * Look up coordinates for a ZIP code
 * @returns Coordinates if found, null if ZIP code not in our database
 */
export function getCoordinatesForZip(zip: string): Coordinates | null {
	const cleaned = zip.trim().substring(0, 5);
	return ZIP_COORDINATES[cleaned] ?? null;
}

/**
 * Check if a ZIP code is valid (5 digits)
 */
export function isValidZipFormat(zip: string): boolean {
	return /^\d{5}$/.test(zip.trim());
}

/**
 * Check if a ZIP code starts with a San Diego County prefix, so a lookup
 * miss could be a gap in our data rather than a ZIP from elsewhere
 */
export function hasCountyZipPrefix(zip: string): boolean {
	return COUNTY_ZIP_PREFIXES.some((prefix) => zip.trim().startsWith(prefix));
}
